 if(key==='long-lead')return [['reference','Package'],['description','Description'],['sourceRequiredOnSite','Register required on site'],['programmeNeedDate','Programme need'],['needDate','Assessed need date'],['needDateBasis','Need date basis'],['forecastDelivery','Forecast delivery'],['actualDelivery','Actual delivery'],['headroomCalendarDays','Headroom to assessed date · days'],['linkedFloatHours','Linked float'],['drivingPath','Driving path'],['currentStatus','Status'],['authority','Basis']];
 if(key==='procurement-readiness'||key==='construction-readiness')return [['reference','Package / workfront'],['description','Work'],['discipline','Discipline'],['state','Readiness'],['missingInputs','Unresolved evidence'],['deliveryDateConflict','Delivery date conflict'],['linkedSubmittals','Linked submittals'],['readinessPercent','Satisfied gates %'],['applicableCount','Applicable gates'],['notApplicableCount','N/A gates'],['unknownCount','Unknown gates']];
