 if(key==='delivery-permits')return [['reference','Permit'],['description','Permit type'],['permitStatus','Current validity'],['openWorkAnswer','Effect on open work'],['workLinkLabel','Linked by'],['issuingAuthority','Issuing authority'],['validFrom','Valid from'],['expiryDate','Expiry'],['dueDate','Required by'],['owner','Accountable owner']];
 if(key==='delivery-spares')return [['reference','Part / tool'],['unit','Unit'],['required','Required'],['delivered','Delivered'],['accepted','Accepted'],['stored','Stored'],['handedOver','Handed over'],['remaining','Remaining'],['quantityExceptions','Quantity exceptions']];
 if(['delivery-control','procurement-packages'].includes(key))return [['reference','Package'],['discipline','Discipline'],['owner','Owner'],['currentStage','Current stage'],['actualDelivery','Actual delivery'],['sourceRequiredOnSite','Register required on site'],['programmeNeedDate','Programme need'],['needDate','Assessed need date'],['needDateBasis','Need date basis'],['forecastDelivery','Forecast delivery'],['headroomCalendarDays','Headroom to assessed date · days'],['deliveryTimingBasis','Delivery / timing basis']];
 if(key==='delivery-suppliers')return [['reference','Supplier'],['description','Company / scope'],['packageCount','Linked packages'],['lateKnownPackageCount','Late · known'],['unresolvedPackageCount','Dates unresolved']];
 if(key==='delivery-assets')return [['reference','Asset'],['description','Description'],['system','System'],['location','Location'],['criticality','Criticality'],['tagInstalledStatus','Tag installed · source'],['commissionedStatus','Commissioned · source'],['omManualStatus','O&M manual · source'],['warrantyStatus','Warranty · source'],['statusAsOfIso','Source status date'],['installationDate','Installation date'],['commissioningDate','Commissioning date'],['takingOverDate','Taking-over date']];
 if(key==='delivery-weather')return [['reference','Event'],['eventStart','From'],['eventEnd','To'],['durationHours','Recorded duration · hours'],['recordedWorkingImpactHours','Recorded working impact · hours'],['claimIds','Existing claims links']];
 if(key==='delivery-risks')return [['riskId','Risk ID'],['description','Risk'],['status','Status'],['sourceStatus','Source status'],['reportingScope','Reporting date basis'],['rating','Source rating'],['probability','Probability'],['impact','Impact'],['score','Score'],['scoreRank','Score rank'],['lastReviewedIso','Last reviewed'],['reviewBasis','Review status'],['dueIso','Action due'],['owner','Owner']];
 return [['reference','Reference'],['description','Description'],['discipline','Discipline'],['currentStatus','Position at Data Date'],['dueDate','Required by'],['overdue','Overdue'],['owner','Owner']];
