 if(record){el('deliverySupersedes').value=data.history?.at(-1)?.supersedesId||'';el('deliveryDecision').value=['working','governed','verified','scenario'].includes(record.state)?record.state:'working';deliveryRenderLinks();el('deliveryLinkSearch').onclick=deliverySearchLinks;el('deliveryAllocationAdd').onclick=()=>{const c=deliveryEditorContext,item=el('deliveryAllocationItem').value,quantity=Number(el('deliveryAllocationQty').value),unit=el('deliveryAllocationUnit').value;if(!item||!el('deliveryAllocationQty').value.trim()||!Number.isFinite(quantity)||quantity<0||!unit)return deliveryShowError(new Error('Select a linked item and enter its quantity and exact unit.'));c.links.boqAllocations=c.links.boqAllocations.filter(x=>x.boqItemId!==item).concat({boqItemId:item,quantity,unit});deliveryRenderLinks();};}
 el('deliveryEvidenceLoad').onclick=deliveryLoadEvidence;el('deliverySave').onclick=deliverySave;target.scrollIntoView({behavior:'smooth',block:'start'});
