function deliveryRenderLinks(){const c=deliveryEditorContext;if(!c)return;el('deliveryLinks').innerHTML=Object.entries(c.links).filter(([key])=>key!=='boqAllocations').map(([key,values])=>'<p><b>'+escapeHtml(deliveryLabel(key))+'</b> '+(values.length?values.map(id=>'<span>'+escapeHtml(c.linkLabels[id]||id)+' <button class="btn small" data-delivery-unlink="'+key+'" data-id="'+escapeHtml(id)+'">Remove</button></span>').join(' '):'No relationship selected')+'</p>').join('');el('deliveryAllocationItem').innerHTML=c.links.boqItemIds.map(id=>'<option value="'+escapeHtml(id)+'">'+escapeHtml(c.linkLabels[id]||id)+'</option>').join('');el('deliveryAllocations').innerHTML=c.links.boqAllocations.map(a=>'<p>'+escapeHtml((c.linkLabels[a.boqItemId]||a.boqItemId)+' · '+a.quantity+' '+a.unit)+' <button class="btn small" data-delivery-allocation-remove="'+escapeHtml(a.boqItemId)+'">Remove</button></p>').join('');}
async function deliverySearchLinks(){const c=deliveryEditorContext;if(!c||project()!==c.projectId)return;const field=el('deliveryLinkType').value,kind={activityIds:'activity',boqItemIds:'boq',packageIds:'package',supplierIds:'supplier',locationIds:'location',assetIds:'asset',recordIds:'',riskIds:'risk',claimIds:'claim',noticeIds:'notice',variationIds:'variation'}[field];try{const data=await api('/api/projects/'+encodeURIComponent(c.projectId)+'/delivery/catalog?kind='+kind+'&q='+encodeURIComponent(el('deliveryLinkQuery').value));if(c!==deliveryEditorContext||project()!==c.projectId)return;data.rows.forEach(r=>c.linkLabels[r.id]=r.label);el('deliveryLinkResults').innerHTML='<p>'+data.total+' matches · showing first '+data.rows.length+'. Narrow the search if necessary.</p>'+data.rows.map(r=>'<p>'+escapeHtml(r.label)+' <button class="btn small" data-delivery-link="'+field+'" data-id="'+escapeHtml(r.id)+'">Link</button></p>').join('');}catch(e){deliveryShowError(e);}}
