async function deliverySave(){const c=deliveryEditorContext;if(!c||project()!==c.projectId)return;const fields={};el('deliveryEditor').querySelectorAll('[data-delivery-field]').forEach(input=>fields[input.dataset.deliveryField]=input.value.trim()||null);let body={action:c.record?'review':'create',kind:c.kind,expectedVersion:c.version,fields};if(c.record)Object.assign(body,{recordId:c.record.recordId,sourceRevision:c.record.revision,state:el('deliveryDecision').value,note:el('deliveryDecisionNote').value,links:c.links,supersedesId:el('deliverySupersedes').value||null});const selectedEvidence=el('deliveryReceiptDocument')?.value;if(selectedEvidence){const doc=c.evidenceDocuments[Number(selectedEvidence)];body.receipts=[{documentId:doc.documentId,sourceHash:doc.sourceHash,locator:el('deliveryReceiptLocator').value}];}const button=el('deliverySave');button.disabled=true;try{await api('/api/projects/'+encodeURIComponent(c.projectId)+'/delivery/records',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});if(project()===c.projectId)await loadModule(selected);}catch(e){if(c===deliveryEditorContext){deliveryShowError(e);el('deliveryError').hidden=false;button.disabled=false;}}}
